// Quick start
import { Button } from 'v12-ui';
import 'v12-ui/styles.css';

<Button variant='primary'>Click me</Button>

// Tree-shakeable - only import what you use
import { Button, Stack } from 'v12-ui';
import 'v12-ui/styles.css';

// npm i v12-ui

// Button adapts to context
<Button variant='primary'>Button</Button>
<Button as='a' href='/docs'>Link</Button>

// Text and Stack are polymorphic
<Text as='h1' variant='hero'>Title</Text>
<Stack as='section' direction='col'>Content</Stack>

// MagicText - particles form text
<MagicText text='Hello' colors={['#0d9488', '#14b8a6']} />

// MagicMouseFollower - cursor particle trail
<MagicMouseFollower particleCount={30} />

// Toggle - WAI-ARIA switch
<Toggle aria-label='Enable notifications' />

// Select - WAI-ARIA combobox
<Select aria-label='Choose an option'>
  <Select.Option value='1'>Option 1</Select.Option>
</Select>

// Redis stores active refresh tokens
// On refresh: previous token is invalidated (rotation)
// If a token is stolen, next refresh detects it

.card-inner {
  transition: transform 0.6s;
  transform-style: preserve-3d;
}
.card.flipped .card-inner {
  transform: rotateY(180deg);
}
